import {cartoonCast as cast, plantDrawing, leafDrawing} from './factory-art.js?v=1';
import {icon, title, next, complete, state, chime} from './app.js?v=7';

// One explanation stop, two ways to learn. The original story remains at #story.
const movie = [
  {pose:'lunch', who:'Beep', line:'Lunch delivery! One sandwich for my leafy friend.', seconds:6},
  {pose:'nope', who:'Sprout', line:'Thanks, Beep! But I make my own food. My leaves have a secret…', seconds:8},
  {pose:'soil', who:'Beep', line:'So the soil is your food?', seconds:5},
  {pose:'roots', who:'Sprout', line:'No! My roots absorb water and minerals. Most of my food-making happens up here, in my leaves.', seconds:10},
  {pose:'zoom', who:'Sprout', line:'It’s called photosynthesis. Let’s follow the water, then take a closer look at a leaf!', seconds:7}
];
const demo = [
  {focus:'water', who:'Water', line:'Up we go! Roots absorb water. It travels inside the stem and into the veins of the leaves. Follow the blue route!', seconds:9},
  {focus:'air', who:'Sprout', line:'Carbon dioxide is a gas in the air. It enters through tiny openings in a leaf.', seconds:9},
  {focus:'light', who:'Sprout', line:'The green chloroplasts inside leaf cells contain chlorophyll. This green pigment absorbs sunlight. This gives the process energy!', seconds:10},
  {focus:'make', who:'Sprout', line:'With that energy, the leaf uses water and carbon dioxide to make glucose, a sugar, and oxygen.', seconds:10},
  {focus:'gifts', who:'Sprout', line:'Glucose is my food. Some is stored as starch. Oxygen goes into the air. Living things use it to breathe!', seconds:11}
];
const $ = s => document.querySelector(s);
let phase, step, elapsed, lastTick, loop, paused, voices, water, gas, light, making, made, waterBusy, timers=[], visits=new Set(), generation=0;
const later=(fn,ms)=>{const token=generation;const id=setTimeout(()=>{if(token===generation)fn()},ms);timers.push(id);return id};
function cancelActions(){generation++;timers.forEach(clearTimeout);timers=[];waterBusy=false;if('speechSynthesis'in window)speechSynthesis.cancel()}
export function cleanupFactory(){clearInterval(loop);loop=undefined;cancelActions();document.removeEventListener('visibilitychange',onVisibility);$('#settings')?.removeEventListener('click',onSettings)}
function speak(text){if(!voices||!('speechSynthesis'in window))return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=.94;speechSynthesis.speak(u)}catch{}}
function say(who,text){$('#factory-speaker').textContent=who;$('#factory-line').textContent=text;$('#guide-face').innerHTML=cast(who==='Beep'?'robot':who==='Water'?'drop':'sprout');speak(text)}

const sandwich=`<svg viewBox="0 0 140 100" aria-hidden="true"><path d="M12 61 73 17 130 64 75 92Z" fill="#dd9850" stroke="#695337" stroke-width="4"/><path d="M12 51 73 9 130 54 75 80Z" fill="#ffe5a3" stroke="#695337" stroke-width="4"/><path d="m19 61 15 2 13 13 14-2 15 9 13-10 15-4 18-9" fill="none" stroke="#66ab52" stroke-width="9"/><path d="m35 49 37-26 34 26-32 17Z" fill="#fff2c5"/></svg>`;
const soil=`<svg viewBox="0 0 140 110" aria-hidden="true"><path d="m32 42 10 55h60l12-55" fill="#e79769" stroke="#6d5344" stroke-width="4"/><ellipse cx="72" cy="43" rx="45" ry="15" fill="#806346" stroke="#6d5344" stroke-width="4"/><path d="m40 41 20-19 20 8 18 10" fill="#806346"/><path d="m57 40 4-3m24 6 6-3" stroke="#dec598" stroke-width="4"/></svg>`;

function factoryStage(){return `<div class="leaf-workshop svg-workshop" id="leaf-workshop" data-focus="water">
  <div class="science-scenes">
    <section class="plant-panel" aria-label="The whole plant">
      <div class="scene-heading"><span class="scene-number">1</span><div><b>Follow the water</b><small>Roots → stem → leaf</small></div></div>
      ${plantDrawing()}
      <div class="plant-actions">
        <div class="water-action"><button id="water-pump" class="scene-action water-action-button">${icon('drop')} <span>Trace the water <small id="pump-count">Start at the roots</small></span></button><span id="water-count" class="action-hint">Watch the route inside the plant.</span></div>
        <label class="light-action"><b>${icon('sun')} Let the sunlight in</b><input id="sunlight-slider" type="range" min="0" max="100" value="0" step="10" aria-label="Move the cloud to let sunlight reach the leaf"><small>Slide to move the cloud →</small></label>
      </div>
    </section>
    <section class="leaf-panel" aria-label="A closer look at the same leaf">
      <div class="scene-heading"><span class="scene-number">2</span><div><b>A closer look</b><small>A slice through that same leaf</small></div><span class="zoom-tag">ZOOM IN</span></div>
      ${leafDrawing()}
      <div class="air-action"><button id="air-help" class="scene-action gas-action-button"><span class="co2-button-symbol">CO₂</span><span>Let carbon dioxide in <small id="gas-count">Through a tiny leaf opening</small></span>${icon('arrow')}</button><button data-carbon="0" class="carbon-bubble" hidden aria-label="Let carbon dioxide enter the leaf"></button></div>
    </section>
  </div>
  <div id="factory-status" class="science-status" role="status">Let’s follow the ingredients!</div>
  <div class="leaf-products" aria-label="Products of photosynthesis">
    <button id="food-gift" class="science-product food-product" disabled><span class="product-token">G</span><span><b>Glucose</b><small>Food made in the leaf · explore</small></span>${icon('arrow')}</button>
    <button id="oxygen-gift" class="science-product oxygen-product" disabled><span class="product-token">O₂</span><span><b>Oxygen</b><small>Released into the air · explore</small></span>${icon('arrow')}</button>
  </div>
</div>`}

export function factory(){return title('story','Sprout’s food-making secret','Follow the water. Peek inside a leaf. Help it make food.')+`<nav class="explanation-tabs" aria-label="Ways to explore inside a leaf"><a class="active" href="#factory" aria-current="page">${icon('play')} Play the leaf story <span>NEW</span></a><a href="#story">${icon('book')} Picture notes</a></nav>
<section class="leaf-experience" aria-label="Cartoon and playable leaf factory">
  <div class="experience-bar"><div class="episode-tags"><span id="chapter-film" class="active">1 · Cartoon</span><span id="chapter-demo">2 · Watch it work</span><span id="chapter-play">3 · Your turn</span></div><button class="text-btn" id="factory-voice" aria-pressed="false">${icon('volume')} <span>Voices off</span></button></div>
  <div id="factory-visual"><div class="lunch-movie" data-pose="cover"><span class="movie-cloud cloud-a"></span><span class="movie-cloud cloud-b"></span><div class="movie-heading"><span>SPROUT & BEEP IN…</span><h2>The lunch<br>mix-up!</h2><p>A tiny tale about a very clever leaf.</p></div><div class="movie-beep">${cast('robot')}<span class="actor-label">BEEP</span></div><div class="movie-sprout">${cast('sprout')}<span class="actor-label">SPROUT</span></div><div class="lunch-prop">${sandwich}</div><div class="soil-prop">${soil}</div><div class="leaf-magnifier">${icon('leaf')}<span>Let’s look inside!</span></div><span class="movie-flower one">✿</span><span class="movie-flower two">✿</span><button id="start-movie" class="btn yellow">${icon('play')} Play the cartoon</button></div></div>
  <div class="factory-narrator"><div id="guide-face">${cast('sprout')}</div><div class="narrator-caption" aria-live="polite" aria-atomic="true"><b id="factory-speaker">Sprout</b><p id="factory-line">Beep has brought me lunch. There’s just one tiny problem…</p></div><button id="replay-line" class="icon-btn" aria-label="Read this caption aloud">${icon('volume')}</button></div>
  <div class="experience-transport"><div><button id="factory-pause" class="text-btn" hidden>Pause</button><span id="experience-position">About 3 minutes · no timer to beat</span></div><div><button id="restart-factory" class="text-btn" hidden>Watch again</button><button id="jump-factory" class="text-btn">Go to the demonstration ${icon('arrow')}</button></div></div>
  <div class="episode-progress" aria-hidden="true"><span id="episode-progress"></span></div>
</section>
<div id="factory-celebration" class="factory-celebration" hidden></div>
<p class="factory-model-note">${icon('lightbulb')} A simplified model: blue marks show water inside the plant; purple and blue arrows show gases moving through a leaf opening. Drawings are enlarged. Symbols and timing are teaching aids.</p>
<details class="transcript"><summary>The whole story, in words</summary><p>${movie.map(x=>`<b>${x.who}:</b> ${x.line}`).join(' ')}</p><h3>Inside the leaf</h3>${demo.map(x=>`<p>${x.line}</p>`).join('')}<p><b>Water + carbon dioxide → glucose + oxygen</b>, using light energy absorbed by chlorophyll. Sunlight supplies energy; it is not a raw material. Plants also respire, during day and night.</p><p>Keyboard or touch: trace the water, let carbon dioxide enter, then slide the cloud away. The leaf starts automatically. Explore both products to finish. In reduced-motion mode, clear end states replace travelling animations.</p><p class="caption">Diagram references: <a href="https://www.rhs.org.uk/advice/understanding-plants/how-plants-absorb-water" target="_blank" rel="noopener">RHS: water transport</a> · <a href="https://www.rhs.org.uk/advice/understanding-plants/how-plants-breathe" target="_blank" rel="noopener">RHS: leaf gas exchange</a> · <a href="https://www.rhs.org.uk/advice/understanding-plants/how-plants-use-light-to-grow" target="_blank" rel="noopener">RHS: chlorophyll and light</a>. Blue water-flow marks show direction inside vessels; they are not airborne droplets. The close-up shows water moving from a vein towards leaf cells. Green ovals represent chloroplasts, which contain chlorophyll.</p><p class="caption">Science Year 4 · Unit 4 · printed pages 76–81. This is an alternative to the picture notes at this same learning stop.</p></details>`+next('story','Try the leaf lab',true)}

export function bindFactory(){cleanupFactory();phase='cover';step=0;elapsed=0;paused=false;voices=!!state.settings.sound;visits=new Set();updateVoice();$('#start-movie').onclick=startMovie;$('#jump-factory').onclick=()=>startDemo();$('#restart-factory').onclick=startMovie;$('#factory-pause').onclick=()=>setPaused(!paused);$('#factory-voice').onclick=()=>{voices=!voices;updateVoice();if(voices&&!paused)speak($('#factory-line').textContent);else if('speechSynthesis'in window)speechSynthesis.cancel()};$('#replay-line').onclick=()=>{if(!('speechSynthesis'in window)){say('Sprout','A voice is not available here. You can read every line in the captions.');return}voices=true;updateVoice();speak($('#factory-line').textContent)};document.addEventListener('visibilitychange',onVisibility);$('#settings').addEventListener('click',onSettings)}
function updateVoice(){$('#factory-voice').setAttribute('aria-pressed',voices);$('#factory-voice span').textContent=voices?'Voices on':'Voices off'}
function onSettings(){if(['movie','demo'].includes(phase))setPaused(true)}
function onVisibility(){if(document.hidden&&['movie','demo'].includes(phase))setPaused(true)}
function setPaused(value){paused=value;$('.leaf-experience')?.classList.toggle('is-paused',paused);$('#factory-pause').textContent=paused?'Resume':'Pause';if('speechSynthesis'in window){if(paused)speechSynthesis.pause();else speechSynthesis.resume()}lastTick=performance.now()}
function chapter(which){for(const name of ['film','demo','play'])$('#chapter-'+name).classList.toggle('active',name===which)}
function startClock(){clearInterval(loop);lastTick=performance.now();loop=setInterval(()=>{const now=performance.now();if(!paused){elapsed+=(now-lastTick)/1000;const sequence=phase==='movie'?movie:demo;const total=sequence.reduce((n,x)=>n+x.seconds,0);const before=sequence.slice(0,step).reduce((n,x)=>n+x.seconds,0);$('#episode-progress').style.width=Math.min(100,(before+elapsed)/total*100)+'%';if(elapsed>=sequence[step].seconds){elapsed=0;step++;if(step===sequence.length){clearInterval(loop);if(phase==='movie')startDemo();else readyToPlay();return}if(phase==='movie')showMovieBeat();else showDemoBeat()}}lastTick=now},100)}
function startMovie(){cancelActions();clearInterval(loop);const oldVisual=$('#factory-visual');if(!oldVisual.querySelector('.lunch-movie')){const holder=document.createElement('div');holder.innerHTML=factory();oldVisual.innerHTML=holder.querySelector('#factory-visual').innerHTML}phase='movie';step=0;elapsed=0;setPaused(false);chapter('film');$('#factory-celebration').hidden=true;$('#start-movie').hidden=true;$('#factory-pause').hidden=false;$('#restart-factory').hidden=false;$('#jump-factory').className='text-btn';$('#jump-factory').hidden=false;$('#jump-factory').innerHTML='Go to the demonstration '+icon('arrow');$('#jump-factory').onclick=startDemo;$('#experience-position').textContent='The lunch mix-up · 36-second cartoon';showMovieBeat();startClock()}
function showMovieBeat(){const beat=movie[step];$('.lunch-movie').dataset.pose=beat.pose;say(beat.who,beat.line);$('.movie-beep').classList.toggle('speaking',beat.who==='Beep');$('.movie-sprout').classList.toggle('speaking',beat.who==='Sprout')}
function resetMaterials(){water=0;gas=0;light=0;making=false;made=false;visits=new Set()}
function startDemo(){cancelActions();clearInterval(loop);phase='demo';step=0;elapsed=0;resetMaterials();setPaused(false);chapter('demo');$('#factory-visual').innerHTML=factoryStage();$('#factory-celebration').hidden=true;$('#factory-pause').hidden=false;$('#restart-factory').hidden=false;$('#jump-factory').hidden=true;$('#experience-position').textContent='Watch Sprout show you · then you can try';$('#episode-progress').style.width='0';bindWorkshop();lockControls(true);showDemoBeat();startClock()}
function showDemoBeat(){const beat=demo[step];$('#leaf-workshop').dataset.focus=beat.focus;say(beat.who,beat.line);if(step===0){$('#factory-status').textContent='Water’s journey: roots → stem → leaf';water=1;$('#leaf-workshop').classList.add('water-arrived');$('#water-count').textContent='roots → stem → leaf';$('#pump-count').textContent='Water arrived ✓'}if(step===1){$('#factory-status').textContent='Carbon dioxide comes in from the air.';gas=1;$('#leaf-workshop').classList.add('gas-arrived');document.querySelectorAll('[data-carbon]').forEach(b=>b.classList.add('absorbed'));$('#gas-count').textContent='air → tiny openings → leaf'}if(step===2){$('#factory-status').textContent='Chlorophyll catches the Sun’s energy!';light=100;$('#sunlight-slider').value='100';$('#leaf-workshop').style.setProperty('--sunlight',1);$('#leaf-workshop').classList.add('light-arrived')}if(step===3){$('#leaf-workshop').classList.add('is-making');$('#factory-status').textContent='Photosynthesis! The leaf is making food.'}if(step===4){$('#leaf-workshop').classList.remove('is-making');$('#leaf-workshop').classList.add('has-products');$('#factory-status').textContent='Glucose made. Oxygen released!'} }
function readyToPlay(){phase='ready';$('#factory-pause').hidden=true;$('#episode-progress').style.width='100%';$('#experience-position').textContent='You’ve seen it. Now bring the leaf to life!';$('#jump-factory').hidden=false;$('#jump-factory').className='btn yellow';$('#jump-factory').innerHTML='My turn! '+icon('game');$('#jump-factory').onclick=startPlay;say('Sprout','Now you know my secret! Ready to run the leaf yourself?')}
function startPlay(){cancelActions();clearInterval(loop);phase='play';resetMaterials();setPaused(false);chapter('play');$('#factory-visual').innerHTML=factoryStage();$('#factory-celebration').hidden=true;$('#factory-pause').hidden=true;$('#jump-factory').hidden=true;$('#jump-factory').className='text-btn';$('#experience-position').textContent='Your turn · explore at your own pace';$('#episode-progress').style.width='0';bindWorkshop();lockControls(false);updatePlay();$('#water-pump').focus({preventScroll:true})}
function lockControls(lock){document.querySelectorAll('#water-pump,#air-help,#sunlight-slider,[data-carbon]').forEach(b=>b.disabled=lock);$('#leaf-workshop').classList.toggle('demonstrating',lock)}
function bindWorkshop(){$('#water-pump').onclick=sendWater;document.querySelectorAll('[data-carbon]').forEach(b=>b.onclick=()=>sendGas(b));$('#air-help').onclick=()=>{const b=$('[data-carbon]:not(.absorbed)');if(b)sendGas(b)};$('#sunlight-slider').oninput=e=>{light=Number(e.target.value);$('#leaf-workshop').style.setProperty('--sunlight',light/100);$('#leaf-workshop').classList.toggle('light-arrived',light>0);updatePlay()};$('#food-gift').onclick=()=>openGift('food');$('#oxygen-gift').onclick=()=>openGift('oxygen')}
function sendWater(){if(water>=1||waterBusy||phase!=='play'||making||made)return;waterBusy=true;$('#water-pump').disabled=true;$('#water-count').textContent='Following water inside the plant…';const path=$('#water-route'),drop=$('#water-traveller');const reduced=state.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;const length=path.getTotalLength(),duration=reduced?0:2800,start=performance.now(),token=generation;drop.setAttribute('visibility','visible');function travel(now){if(token!==generation)return;const fraction=duration?Math.min((now-start)/duration,1):1;const p=path.getPointAtLength(fraction*length);drop.setAttribute('transform',`translate(${p.x} ${p.y})`);if(fraction<1)requestAnimationFrame(travel);else{drop.setAttribute('visibility','hidden');water=1;waterBusy=false;$('#pump-count').textContent='Water arrived ✓';$('#water-count').textContent='Root → stem → leaf vein';$('#leaf-workshop').classList.add('water-arrived');updatePlay()}}requestAnimationFrame(travel)}
function sendGas(button){if(button.disabled||button.classList.contains('absorbed')||phase!=='play'||making||made)return;button.classList.add('absorbed');button.disabled=true;gas++;$('#gas-count').textContent='Carbon dioxide entered ✓';$('#leaf-workshop').classList.add('gas-arrived');$('#air-help').disabled=gas>=1;updatePlay()}
function updatePlay(){if(phase!=='play'||making||made)return;const focus=water<1?'water':gas<1?'air':light===0?'light':'make';$('#leaf-workshop').dataset.focus=focus;$('#episode-progress').style.width=((water+gas+(light>0?1:0))/3*75)+'%';const messages={water:['Water','Tap “Trace the water”. Follow the blue route from a root, inside the stem, into a leaf vein.'],air:['Sprout','Water has arrived inside the leaf. Now let carbon dioxide in. Watch it enter through a tiny opening on the underside.'],light:['Sprout','Water and carbon dioxide are here. Slide the cloud away! Chlorophyll inside leaf cells absorbs light energy.']};if(messages[focus]){const [who,line]=messages[focus];if($('#factory-line').textContent!==line)say(who,line);$('#factory-status').textContent=focus==='water'?'Water travels up from the roots.':focus==='air'?'Carbon dioxide enters the leaf.':'Chlorophyll needs light to absorb.'}else produce()}
function produce(){making=true;lockControls(true);$('#leaf-workshop').classList.add('is-making');$('#factory-status').textContent='Photosynthesis in action!';say('Sprout','The green leaf has water, carbon dioxide and light. Photosynthesis makes glucose and releases oxygen.');later(()=>{making=false;made=true;$('#leaf-workshop').classList.remove('is-making','demonstrating');$('#leaf-workshop').classList.add('has-products');$('#leaf-workshop').dataset.focus='gifts';$('#factory-status').textContent='You helped a leaf make its own food!';$('#food-gift').disabled=false;$('#oxygen-gift').disabled=false;$('#episode-progress').style.width='90%';say('Sprout','Two products! Tap glucose and oxygen to see where they go.');chime()},voices?9000:state.settings.motion?1800:6000)}
function openGift(kind){if(!made)return;visits.add(kind);$('#'+kind+'-gift').classList.add('explored');const food=kind==='food';say('Sprout',food?'Glucose is a sugar: food the plant uses for energy and growth. Some is stored as starch. Plants also provide food for animals!':'Oxygen leaves the leaf and enters the air. Animals and plants use oxygen when they respire. Plants respire in the day and at night.');const box=$('#factory-celebration');box.hidden=false;box.innerHTML=`<div class="gift-reveal">${food?cast('sprout'):'<span class="oxygen-portrait" aria-hidden="true">O₂</span>'}<div><span class="eyebrow">${food?'FOOD FOR LIFE':'A GIFT TO THE AIR'}</span><h2>${food?'Made in a leaf. Shared through life.':'A little leaf helps living things breathe.'}</h2><p>${food?'Glucose feeds the plant. Some is stored as starch. When a caterpillar eats a leaf, it gets food made by the plant.':'Photosynthesis releases oxygen. Living things, including plants, use oxygen for respiration.'}</p><div class="gift-path">${food?'<span>🍃 Plant</span><b>→</b><span>🐛 Caterpillar</span><b>→</b><span>🐦 Bird</span>':'<span>🍃 Leaf</span><b>→</b><span>O₂ in the air</span><b>→</b><span>🐇 Living things</span>'}</div></div></div>${visits.size===2?`<div class="factory-finished"><b>${icon('star')} High-leaf! You know the leaf’s secret.</b><button id="play-factory-again" class="btn secondary">Run the leaf again</button><a href="#lab" class="btn">Let’s experiment ${icon('arrow')}</a></div>`:`<p class="gift-nudge">Now explore ${food?'oxygen':'glucose'} to follow the other product.</p>`}`;if(visits.size===2){complete('story');$('#episode-progress').style.width='100%';$('#play-factory-again').onclick=startPlay}}
